var roots=new[]{"Assets/Magic Pig Games (Infinity PBR)/HOVL - Toon Projectiles 2","Assets/Eric VFX Studio/Free Game VFX/Prefab","Assets/Vefects/Zap VFX URP/VFX/Zap/Particles"};
return roots.SelectMany(root=>AssetDatabase.FindAssets("t:Prefab",new[]{root})).Select(AssetDatabase.GUIDToAssetPath).Where(p=>!p.Contains("Muzzle")).Select(p=>{var g=AssetDatabase.LoadAssetAtPath<GameObject>(p);var rs=g.GetComponentsInChildren<Renderer>(true);return new {p,ps=g.GetComponentsInChildren<ParticleSystem>(true).Length,missing=rs.Count(r=>!r.sharedMaterial),textures=rs.Where(r=>r.sharedMaterial).Select(r=>r.sharedMaterial.mainTexture?r.sharedMaterial.mainTexture.name:"none").Distinct().ToArray()};}).ToArray();
